const { prepareSource } = (function sourceAdapterRuntime(metadata, fixtures = {}) {
  const DAY = 86400000;
  const clone = value => JSON.parse(JSON.stringify(value));
  function text(value, label) { if (typeof value !== 'string' || !value.trim()) throw new Error(`${label} is required`); const clean = value.trim(); if (clean.length > 2000) throw new Error(`${label} exceeds 2000 characters`); return clean; }
  function num(value, label, min = 0, max = 1e12, integer = false) { if (typeof value === 'string' && value.trim() && /^-?\d+(?:\.\d+)?$/.test(value.trim())) value = Number(value); if (typeof value !== 'number' || !Number.isFinite(value) || value < min || value > max || (integer && !Number.isInteger(value))) throw new Error(`${label} must be ${integer ? 'an integer' : 'numeric'} from ${min} to ${max}`); return value; }
