  function https(value, label) { const clean = text(value, label); if (!/^https:\/\/[^/?#@\s\\]+(?:[/?#][^\s\\]*)?$/i.test(clean)) throw new Error(`${label} must be an absolute HTTPS URL without embedded credentials`); return clean; }
